24	
25	/**
26	 * The claims on a sheet: listed newest first, added to a person and edited one at a time. A claim
27	 * given no date takes the sheet's today. Its due-by is fixed when it is added: its date plus the terms
28	 * in force on that date of its person's grade then (else the sheet's terms in force on it); it does not
29	 * move when its date or the terms change later. A claim is added as DRAFT and moves through its statuses
30	 * as {@link ClaimStatus} allows; a change it does not allow is refused. Opening a claim gives it
31	 * the sheet's next number (or, while the sheet numbers by period, the next within its period), which it
32	 * keeps when voided and is never given again. Only a DRAFT claim
33	 * can be edited; an OPEN one is changed by voiding it and adding a new one. Settling it
34	 * fixes its due at its figure (the due bound by a statement, else its person's grade rate of the
35	 * moment on the claim's date) with its late charge of the moment frozen in; with no figure it
36	 * stays live. A steward can re-settle a SETTLED claim at the figure it would have today as an open claim
37	 * bound by no statement. The user who opened a claim cannot settle it, and a clerk cannot settle one whose
38	 * due is above the sheet's clerk limit (a steward can). A claim with no proofs whose due is above the proof threshold
39	 * in force on its date cannot be settled or approved by anyone. No claim dated inside a closed period can
40	 * be added, edited (to or from such a date), opened, settled, re-settled or voided. No claim can be added
41	 * or edited to a date after its person's retirement date. A claim with a negative amount is a
42	 * correction: it must name, by number, a SETTLED claim of the same person; only a correction may name one.
43	 */
44	@Service
45	public class ClaimService {
46	
47	    private final ClaimRepository claims;
48	    private final PersonRepository people;
49	    private final RateService rates;
50	    private final SheetService sheets;
51	    private final RollupService rollup;
52	    private final PeriodRepository periods;
53	    private final SettingService settings;
54	    private final Audit audit;
55	
56	    public ClaimService(ClaimRepository claims, PersonRepository people, RateService rates, SheetService sheets,
57	            RollupService rollup, PeriodRepository periods, SettingService settings, Audit audit) {
58	        this.settings = settings;
59	        this.periods = periods;
60	        this.claims = claims;
61	        this.people = people;
62	        this.rates = rates;
63	        this.sheets = sheets;
64	        this.rollup = rollup;
65	        this.audit = audit;
66	    }
67	
68	    @Transactional(readOnly = true)
69	    public List<Claim> list(String sheetId) {
70	        return claims.findBySheetIdOrderByListedDesc(sheetId);
71	    }
72	
73	    @Transactional
74	    public Claim add(String sheetId, String user, Long personId, BigDecimal amount, LocalDate date, String note,
75	            String corrects) {
76	        // The snapshot locks the sheet first, so the person is read as retired by any retirement before.
77	        RollupService.Snapshot before = rollup.snapshot(sheetId);
78	        Person person = people.findByIdAndSheetId(personId, sheetId).orElseThrow(PersonNotFoundException::new);
79	        LocalDate on = dateOrToday(sheetId, date);
80	        refuseIfClosed(sheetId, on);
81	        if (!person.mayClaimOn(on)) throw new PersonRetiredException();
82	        refuseUnlessCorrects(sheetId, personId, amount, corrects);
83	        LocalDate dueBy = on.plusDays(settings.termsFor(sheetId, person.gradeOn(on), on));
84	        Claim draft = new Claim(sheetId, personId, amount, on, note, dueBy);
85	        draft.setCorrects(corrects);
86	        Claim claim = claims.saveAndFlush(draft);
87	        logStatus(sheetId, user, person, claim);
88	        claim = claims.saveAndFlush(claim);
89	        record("CLAIM_ADDED", sheetId, user, person, claim);
90	        rollup.recordChanges(sheetId, user, before);
91	        return claim;
92	    }
93	
94	    @Transactional
95	    public Claim edit(String sheetId, String user, Long id, BigDecimal amount, LocalDate date, String note,
96	            String corrects) {
97	        Claim claim = claims.findByIdAndSheetId(id, sheetId).orElseThrow(ClaimNotFoundException::new);
98	        if (claim.getStatus() != ClaimStatus.DRAFT) {
99	            throw new ClaimStatusRefusedException();
100	        }
101	        RollupService.Snapshot before = rollup.snapshot(sheetId);
102	        LocalDate on = dateOrToday(sheetId, date);
103	        refuseIfClosed(sheetId, claim.getDate());
104	        refuseIfClosed(sheetId, on);
105	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId).orElseThrow(PersonNotFoundException::new);
106	        if (!person.mayClaimOn(on)) throw new PersonRetiredException();
107	        refuseUnlessCorrects(sheetId, person.getId(), amount, corrects);
108	        claim.setAmount(amount);
109	        claim.setCorrects(corrects);
110	        claim.setDate(on);
111	        claim.setNote(note);
112	        Claim saved = claims.saveAndFlush(claim);
113	        record("CLAIM_EDITED", sheetId, user, person, saved);
114	        rollup.recordChanges(sheetId, user, before);
115	        return saved;
116	    }
117	
118	    @Transactional
119	    public Claim changeStatus(String sheetId, String user, Long id, ClaimStatus next) {
120	        // Opening takes the sheet's next number, locking the sheet first so the claim is read only
121	        // once no other open on the sheet is under way; a refusal rolls the number back.
122	        Sheet numbering = next == ClaimStatus.OPEN ? sheets.lockForNumbering(sheetId) : null;
123	        Claim claim = claims.findByIdAndSheetId(id, sheetId).orElseThrow(ClaimNotFoundException::new);
124	        String action = switch (next) {
125	            case OPEN -> "open";
126	            case SETTLED -> "settle";
127	            case VOID -> "void";
128	            default -> throw new ClaimStatusRefusedException();
129	        };
130	        if (!settings.mayDo(sheetId, user, action)) throw new ClaimNotPermittedException();
131	        if (!claim.getStatus().canBecome(next)) {
132	            throw new ClaimStatusRefusedException();
133	        }
134	        if (next == ClaimStatus.SETTLED && claim.isDeferredOn(sheets.today(sheetId))) {
135	            throw new ClaimDeferredException();
136	        }
137	        if (next == ClaimStatus.SETTLED && user.strip().equals(claim.getOpenedBy())) {
138	            throw new ClaimSettledByOpenerException();
139	        }
140	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId).orElseThrow(PersonNotFoundException::new);
141	        // Settling freezes the late charge of the moment into the settled due.
142	        BigDecimal settling = next == ClaimStatus.SETTLED ? chargedFigureOf(sheetId, person, claim) : null;
143	        if (next == ClaimStatus.SETTLED) refuseUnproved(sheetId, claim, settling);
144	        if (next == ClaimStatus.SETTLED && overClerkLimit(sheetId, user, settling)) next = ClaimStatus.PENDING;
145	        RollupService.Snapshot before = rollup.snapshot(sheetId);
146	        refuseIfClosed(sheetId, claim.getDate());
147	        switch (next) {
148	            case OPEN -> {
149	                number(numbering, claim);
150	                claim.setOpenedBy(user.strip());
151	            }
152	            case SETTLED -> claim.setSettledDue(settling);
153	            default -> {}
154	        }
155	        claim.setStatus(next);
156	        logStatus(sheetId, user, person, claim);
157	        Claim saved = claims.saveAndFlush(claim);
158	        String event = switch (next) {
159	            case OPEN -> "CLAIM_OPENED";
160	            case PENDING -> "CLAIM_PENDING";
161	            case SETTLED -> "CLAIM_SETTLED";
162	            case VOID -> "CLAIM_VOIDED";
163	            case DRAFT -> throw new IllegalStateException();
164	        };
165	        String due = next == ClaimStatus.SETTLED
166	                ? " due=" + (saved.getSettledDue() == null ? "n/a" : saved.getSettledDue().setScale(2).toPlainString())
167	                : "";
168	        record(event, sheetId, user, person, saved, saved.getNumber(), due);
169	        rollup.recordChanges(sheetId, user, before);
170	        return saved;
171	    }
172	
173	    /** A steward other than its opener approves a PENDING claim: SETTLED, its due fixed at its live due now. */
174	    @Transactional
175	    public Claim approve(String sheetId, String user, Long id) {
176	        // The snapshot locks the sheet first, so the claim is read once no other change is under way.
177	        RollupService.Snapshot before = rollup.snapshot(sheetId);
178	        Claim claim = pendingForSteward(sheetId, user, id);
179	        if (user.strip().equals(claim.getOpenedBy())) throw new ClaimApprovedByOpenerException();
180	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId).orElseThrow(PersonNotFoundException::new);
181	        refuseIfClosed(sheetId, claim.getDate());
182	        BigDecimal settling = chargedFigureOf(sheetId, person, claim);
183	        refuseUnproved(sheetId, claim, settling);
184	        claim.setSettledDue(settling);
185	        claim.setStatus(ClaimStatus.SETTLED);
186	        logStatus(sheetId, user, person, claim);
187	        Claim saved = claims.saveAndFlush(claim);
188	        record("CLAIM_APPROVED", sheetId, user, person, saved, saved.getNumber(), " due="
189	                + (saved.getSettledDue() == null ? "n/a" : saved.getSettledDue().setScale(2).toPlainString()));
190	        rollup.recordChanges(sheetId, user, before);
191	        return saved;
192	    }
193	
194	    /** A steward rejects a PENDING claim with a reason: OPEN again, bound by its person's last statement if it was. */
195	    @Transactional
196	    public Claim reject(String sheetId, String user, Long id, String reason) {
197	        // The snapshot locks the sheet first, so the claim is read once no other change is under way.
198	        RollupService.Snapshot before = rollup.snapshot(sheetId);
199	        Claim claim = pendingForSteward(sheetId, user, id);
200	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId).orElseThrow(PersonNotFoundException::new);
201	        refuseIfClosed(sheetId, claim.getDate());
202	        claim.setStatus(ClaimStatus.OPEN);
203	        logStatus(sheetId, user, person, claim);
204	        Claim saved = claims.saveAndFlush(claim);
205	        record("CLAIM_REJECTED", sheetId, user, person, saved, saved.getNumber(), " reason=" + reason);
206	        rollup.recordChanges(sheetId, user, before);
207	        return saved;
208	    }
209	
210	    /**
211	     * A steward re-settles a SETTLED claim: its due fixed again at the figure it would have today as an
212	     * open claim bound by no statement (the rate, grade, floor and late percent in force on its date, the
213	     * late charge as of today). Refused for anyone
214	     * else, a claim in any other status, or one dated inside a closed period.
215	     */
216	    @Transactional
217	    public Claim resettle(String sheetId, String user, Long id) {
218	        // The snapshot locks the sheet first, so the claim is read once no other change is under way.
219	        RollupService.Snapshot before = rollup.snapshot(sheetId);
220	        Claim claim = claims.findByIdAndSheetId(id, sheetId).orElseThrow(ClaimNotFoundException::new);
221	        if (claim.getStatus() != ClaimStatus.SETTLED) throw new ClaimStatusRefusedException();
222	        if (settings.roleOf(sheetId, user) != Role.STEWARD) throw new ClaimNotStewardException();
223	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId).orElseThrow(PersonNotFoundException::new);
224	        refuseIfClosed(sheetId, claim.getDate());
225	        BigDecimal old = claim.getSettledDue();
226	        BigDecimal figure = LateCharge.withChargeAsOpen(claim, dueOf(sheetId, person, claim), sheets.today(sheetId),
227	                d -> settings.latePctOn(sheetId, d), roundingOf(sheetId, claim));
228	        claim.setSettledDue(figure);
229	        logStatus(sheetId, user, person, claim);
230	        Claim saved = claims.saveAndFlush(claim);
231	        record("CLAIM_RESETTLED", sheetId, user, person, saved, saved.getNumber(),
232	                " old=" + figureText(old) + " new=" + figureText(figure));
233	        rollup.recordChanges(sheetId, user, before);
234	        return saved;
235	    }
236	
237	    /** A fixed due as an audit line has it: two decimals, or n/a when none. */
238	    private static String figureText(BigDecimal due) {
239	        return due == null ? "n/a" : due.setScale(2).toPlainString();
240	    }
241	
242	    /**
243	     * A user whose role may reassign (a steward, unless the permission matrix says otherwise) moves a DRAFT, OPEN or PENDING claim to another person on the sheet. It keeps its number
244	     * and date, loses any figure a statement bound it to (live again until its new person's next
245	     * statement), and is listed as its new person's newest claim. A SETTLED or VOID claim cannot move,
246	     * nor one dated inside a closed period, nor one dated after its new person's retirement date.
247	     */
248	    @Transactional
249	    public Claim reassign(String sheetId, String user, Long id, Long toPersonId) {
250	        // The snapshot locks the sheet first, so the claim is read once no other change is under way.
251	        RollupService.Snapshot before = rollup.snapshot(sheetId);
252	        Claim claim = claims.findByIdAndSheetId(id, sheetId).orElseThrow(ClaimNotFoundException::new);
253	        ClaimStatus status = claim.getStatus();
254	        if (status != ClaimStatus.DRAFT && !status.isOpen()) throw new ClaimStatusRefusedException();
255	        if (!settings.mayDo(sheetId, user, "reassign")) throw new ClaimNotPermittedException();
256	        Person from = people.findByIdAndSheetId(claim.getPersonId(), sheetId).orElseThrow(PersonNotFoundException::new);
257	        Person to = people.findByIdAndSheetId(toPersonId, sheetId).orElseThrow(PersonNotFoundException::new);
258	        if (from.getId().equals(to.getId())) throw new ClaimReassignRefusedException();
259	        refuseIfClosed(sheetId, claim.getDate());
260	        if (!to.mayClaimOn(claim.getDate())) throw new PersonRetiredException();
261	        claim.unstate();
262	        claim.moveTo(to.getId(), claims.nextListed());
263	        Claim saved = claims.saveAndFlush(claim);
264	        record("CLAIM_REASSIGNED", sheetId, user, to, saved, saved.getNumber(),
265	                " from=" + from.getName() + " to=" + to.getName());
266	        rollup.recordChanges(sheetId, user, before);
267	        return saved;
268	    }
269	
270	    /**
271	     * Defer an OPEN claim until a date after the sheet's today: until the sheet's today reaches it the claim
272	     * counts in no total, is not overdue, cannot be settled and is left unbound by a statement. Refused for a
273	     * claim that is not OPEN, a date not after today, or a claim dated inside a closed period.
274	     */
275	    @Transactional
276	    public Claim defer(String sheetId, String user, Long id, LocalDate until) {
277	        // The snapshot locks the sheet first, so the claim is read once no other change is under way.
278	        RollupService.Snapshot before = rollup.snapshot(sheetId);
279	        Claim claim = claims.findByIdAndSheetId(id, sheetId).orElseThrow(ClaimNotFoundException::new);
280	        if (claim.getStatus() != ClaimStatus.OPEN) throw new ClaimStatusRefusedException();
281	        if (!until.isAfter(sheets.today(sheetId))) throw new ClaimDeferDateException();
282	        refuseIfClosed(sheetId, claim.getDate());
283	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId).orElseThrow(PersonNotFoundException::new);
284	        claim.setDeferredUntil(until);
285	        Claim saved = claims.saveAndFlush(claim);
286	        record("CLAIM_DEFERRED", sheetId, user, person, saved, saved.getNumber(), " until=" + until);
287	        rollup.recordChanges(sheetId, user, before);
288	        return saved;
289	    }
290	
291	    /**
292	     * Raise a claim's proofs count by one. Refused for a SETTLED or VOID claim, or one dated inside a closed period.
293	     */
294	    @Transactional
295	    public Claim addProof(String sheetId, String user, Long id) {
296	        // The snapshot locks the sheet first, so the claim is read once no other change is under way.
297	        RollupService.Snapshot before = rollup.snapshot(sheetId);
298	        Claim claim = claims.findByIdAndSheetId(id, sheetId).orElseThrow(ClaimNotFoundException::new);
299	        if (claim.getStatus() == ClaimStatus.SETTLED || claim.getStatus() == ClaimStatus.VOID) {
300	            throw new ClaimStatusRefusedException();
301	        }
302	        refuseIfClosed(sheetId, claim.getDate());
303	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId).orElseThrow(PersonNotFoundException::new);
304	        claim.addProof();
305	        Claim saved = claims.saveAndFlush(claim);
306	        record("CLAIM_PROOF_ADDED", sheetId, user, person, saved, saved.getNumber(), " proofs=" + saved.getProofs());
307	        rollup.recordChanges(sheetId, user, before);
308	        return saved;
309	    }
310	
311	    /**
312	     * Refuse settling or approving a claim with no proofs whose due is above the proof threshold in force on
313	     * its date; a due of n/a is within any, and no threshold means none is needed.
314	     */
315	    private void refuseUnproved(String sheetId, Claim claim, BigDecimal due) {
316	        if (claim.getProofs() > 0 || due == null) return;
317	        BigDecimal threshold = settings.proofThresholdOn(sheetId, claim.getDate());
318	        if (threshold != null && due.compareTo(threshold) > 0) throw new ClaimProofRequiredException();
319	    }
320	
321	    /** The PENDING claim a steward approves or rejects; refused when not PENDING or not a steward. */
322	    private Claim pendingForSteward(String sheetId, String user, Long id) {
323	        Claim claim = claims.findByIdAndSheetId(id, sheetId).orElseThrow(ClaimNotFoundException::new);
324	        if (claim.getStatus() != ClaimStatus.PENDING) throw new ClaimStatusRefusedException();
325	        if (settings.roleOf(sheetId, user) != Role.STEWARD) throw new ClaimNotStewardException();
326	        return claim;
327	    }
328	
329	    /**
330	     * Give an opened claim its number: the sheet's next, or while the sheet numbers by period, the next
331	     * within the period its date falls in (in no period: the next in the sheet's X sequence).
332	     */
333	    private void number(Sheet sheet, Claim claim) {
334	        if (!sheet.numbersByPeriod()) {
335	            claim.setNumber(sheet.nextClaimNumber());
336	            return;
337	        }
338	        String period = periods.findBySheetIdOrderByFromDateAsc(sheet.getId()).stream()
339	                .filter(p -> p.contains(claim.getDate()))
340	                .map(Period::getName)
341	                .findFirst().orElse("");
342	        claim.setNumberWithin(period, claims.lastNumberWithin(sheet.getId(), period) + 1);
343	    }
344	
345	    /**
346	     * A claim's figure now: the due fixed when it was settled, else the due bound by its person's
347	     * last statement, else its live due; null when it has none.
348	     */
349	    public BigDecimal figureOf(String sheetId, Person person, Claim claim) {
350	        if (claim.getSettledDue() != null) return claim.getSettledDue();
351	        if (claim.isBound()) return claim.getStatedDue();
352	        return dueOf(sheetId, person, claim);
353	    }
354	
355	    /**
356	     * A claim's due now: its figure, with the late charge on top while it is overdue; null when it
357	     * has none. A statement binds the figure, never the charge.
358	     */
359	    public BigDecimal chargedFigureOf(String sheetId, Person person, Claim claim) {
360	        BigDecimal figure = figureOf(sheetId, person, claim);
361	        if (claim.getSettledDue() != null) return figure;
362	        return LateCharge.withCharge(claim, figure, sheets.today(sheetId),
363	                d -> settings.latePctOn(sheetId, d), roundingOf(sheetId, claim));
364	    }
365	
366	    /** How the claim's live figures round: by its date, or a correction's by its corrected claim's ({@link Rounding}). */
367	    private RoundingMode roundingOf(String sheetId, Claim claim) {
368	        LocalDate basis = Rounding.basisOf(claim,
369	                Rounding.datesByNumber(claims.findBySheetIdAndPersonIdOrderByIdDesc(sheetId, claim.getPersonId())));
370	        return Rounding.of(basis, settings.policyDate(sheetId), sheets.today(sheetId));
371	    }
372	
373	    /**
374	     * A claim's live due: its amount times the rate on its date of its person's grade in force on it, rounded to
375	     * cents as {@link Rounding} has it, and at least the sheet's floor in force on its date unless a correction; null with no rate.
376	     */
377	    private BigDecimal dueOf(String sheetId, Person person, Claim claim) {
378	        BigDecimal floor = claim.isCorrection() ? null : settings.floorOn(sheetId, claim.getDate());
379	        RoundingMode rounding = roundingOf(sheetId, claim);
380	        return rates.on(sheetId, person.gradeOn(claim.getDate()), claim.getDate())
381	                .map(Rate::getPct)
382	                .map(pct -> claim.getAmount().multiply(pct).movePointLeft(2).setScale(2, rounding))
383	                .map(due -> floor == null ? due : due.max(floor))
384	                .orElse(null);
385	    }
386	
387	    /** Log the status the claim now has: by the user on the sheet's today, with its due at this moment. */
388	    private void logStatus(String sheetId, String user, Person person, Claim claim) {
389	        claim.logStatus(user.strip(), sheets.today(sheetId), chargedFigureOf(sheetId, person, claim));
390	    }
391	
392	    private void record(String event, String sheetId, String user, Person person, Claim claim) {
393	        record(event, sheetId, user, person, claim, claim.getNumber(), "");
394	    }
395	
396	    /** A claim's audit line; one about a claim with a number has it, then any extra fields. */
397	    private void record(String event, String sheetId, String user, Person person, Claim claim, String number,
398	            String extra) {
399	        audit.recordOnCommit(event + " sheet=" + sheetId + " by=" + user.strip() + " person=" + person.getName()
400	                + " amount=" + claim.getAmount().setScale(2).toPlainString() + " date=" + claim.getDate()
401	                + (number != null ? " number=" + number : "") + extra);
402	    }
403	
404	    /**
405	     * Refuse a correction that names no SETTLED claim of its person by number, and a claim that names
406	     * one but is not a correction.
407	     */
408	    private void refuseUnlessCorrects(String sheetId, Long personId, BigDecimal amount, String corrects) {
409	        if (amount.signum() >= 0) {
410	            if (corrects != null) throw new CorrectionRefusedException();
411	            return;
412	        }
413	        boolean settled = corrects != null && claims.findBySheetIdAndPersonIdOrderByIdDesc(sheetId, personId).stream()
414	                .anyMatch(c -> corrects.equals(c.getNumber()) && c.getStatus() == ClaimStatus.SETTLED);
415	        if (!settled) throw new CorrectionRefusedException();
416	    }
417	
418	    /** Whether a clerk settles a claim whose due is above the clerk limit; a due of n/a is within any. */
419	    private boolean overClerkLimit(String sheetId, String user, BigDecimal due) {
420	        if (settings.roleOf(sheetId, user) == Role.STEWARD) return false;
421	        BigDecimal limit = settings.clerkLimit(sheetId);
422	        return limit != null && due != null && due.compareTo(limit) > 0;
423	    }
424	
425	    /** Refuse a change to a claim dated inside a closed period; the caller holds the sheet's lock. */
426	    private void refuseIfClosed(String sheetId, LocalDate date) {
427	        if (periods.closedOn(sheetId, date)) throw new PeriodClosedException();
428	    }
429	
430	    private LocalDate dateOrToday(String sheetId, LocalDate date) {
431	        return date != null ? date : sheets.today(sheetId);
432	    }
433	}
